Throughout the paper we restrict the set $\TindexO$ of observed time steps to take one of the following two forms:
\begin{itemize}
\item \textbf{Regular sampling}: All time steps within a time interval $[t-\taumax, t]$ for some non-negative integer $\taumax < \infty$ and a reference time step $t$ are observed, i.e., $\TindexO = \{t-\tau ~|~ 0 \leq \tau \leq \taumax\}$.
\item \textbf{Regular subsampling}: Every $n$-th time step, for $n \geq 2$ an integer, within $[t-\taumax, t]$ with $\taumax < \infty$ is observed, i.e., $\TindexO = \{t-\tau ~|~ 0 \leq \tau \leq \taumax , \, \tau \!\! \mod n = 0\}$.
\end{itemize}

Let $\G = (\V, \E)$ be a directed partial mixed graph with time series structure. The \emph{stationarification} of $\G$, denoted as $\stat(\G)$, is the graph $\stat(\G) = (\V^\prime, \E^\prime)$ defined as follows:
\begin{enumerate}
	\item It has the same set of vertices as $\G$, i.e., $\V^\prime = \V$.
	\item There is an edge $((i, t_i), (j, t_j)) \in \E^\prime_{\bullet}$ with $\bullet \in \{\tailhead, \, \headhead, \, \ohead, \, \oo\}$ if and only if $((i, t_i + \Delta t), (j, t_j + \Delta t)) \in \E_{\bullet}$ in $\G$ for all $\Delta t$ with $(i, t_i + \Delta t), (j, t_j + \Delta t) \in \V$.
\end{enumerate}

Let $\G$ be an acyclic directed mixed graph with time series structure and let $\V = \Iindex \times \Tindex$ with $\Tindex = \{t - \tau ~|~ 0 \leq \tau \leq \taumax\}$ be its set of vertices. Denote with $\E^{\stat}$ the set of edges of $\stat(\G)$. The canonical ts-DAG associated to $\G$, denoted as $\Dc(\G)$, is the graph $\Dc(\G) = (\V^{ca}, \E^{ca})$ defined as follows:
\begin{enumerate}
	\item Its set of vertices is $\V^{ca} = \left(\Iindex \cup \mathbf{J}\right) \times \mathbb{Z}$, where $\mathbf{J} = \{(i, j, \tau) ~|~ ((i, t-\tau), (j, t)) \in \E^{\stat}_{\headhead}\}$. The variable index set is $\Iindex \cup \mathbf{J}$ and the time index set is $\mathbb{Z}$.
	\item Its set of edges $\E^{ca} = \E^{ca}_{\rightarrow}$ are for all $\Delta t \in \mathbb{Z}$
	\begin{itemize}
		\item $(i, t-\tau + \Delta t) \tailhead (j, t + \Delta t)$ for all $((i, t-\tau) , (j, t)) \in \E^{\stat}_{\tailhead}$ and
		\item $((i, j, \tau), t + \Delta t) \tailhead (i, t + \Delta t)$ for all $(i, j, \tau) \in \mathbf{J}$ and
		\item $((i, j, \tau), t -\tau + \Delta t) \tailhead (j, t + \Delta t)$ for all $(i, j, \tau) \in \mathbf{J}$.
	\end{itemize}
\end{enumerate}

Let $\M$ be a DMAG, let $[\M]$ be its Markov equivalence class, and for a background knowledge $\BR$ let $[\M]_{\BR}$ be the subset of $[\M]$ that is consistent with $\BR$, i.e., $[\M]_{\BR} = \{\M \in [\M] ~|~ \BR(\M) = 1\}$. Then:
\begin{enumerate}
\item A directed partial mixed graph $\PAG$ is a \emph{DPAG for $\M$} if
\begin{itemize}
	\item $\PAG$ has the same skeleton (i.e., the same set of adjacencies) as $\M$ and
	\item every non-circle mark in $\PAG$ is also in $\M$.
\end{itemize}
\item A DPAG $\PAG$ for $\M$ is called \emph{maximally informative (m.i.) with respect to $[\M]^\prime \subseteq [\M]$} if
\begin{itemize}
	\item every non-circle mark in $\PAG$ is in every element of $[\M]^\prime$ and
	\item for every circle mark in $\PAG$ there are $\M_1, \M_2 \in [\M]^\prime$ such that in $\M_1$ there is a tail mark and in $\M_2 \in [\M]^\prime$ there is a head mark instead of the circle mark.
\end{itemize}
\item The \emph{maximally informative (m.i.) DPAG with respect to $\BR$}, denoted as $\PAG(\M, \BR)$, is the m.i.~DPAG of $\M$ with respect to $[\M]_{\BR}$.
\item The \emph{conventional m.i.~DPAG for $\M$} is the m.i.~DPAG $\PAG(\M) = \PAG(\M, \BR_{\emptyset})$, where $\BR_{\emptyset}$ is the ``empty'' background knowledge for which $\BR_{\emptyset} = 1$ constant.
\end{enumerate}

The \emph{background knowledge of$\ldots$}
\begin{itemize}
\item $\ldots$ \emph{an underlying ts-DAG} is the background knowledge $\BRtsDAG$ for which $\BRtsDAG(\M) = 1$ if and only if $\M$ is a ts-DMAG, i.e., $\BRtsDAG(\M) = 1$ if and only if there is a ts-DAG $\D$ with $\M = \Mtaumax(\D)$.
\item $\ldots$ \emph{an underlying ts-DAG for stationarifications} is the background knowledge $\BRtsDAGstat$ for which $\BRtsDAGstat(\M) = 1$ if and only if $\M$ is a stationarified ts-DMAG, i.e., $\BRtsDAGstat(\M) = 1$ if and only if there is a ts-DAG $\D$ with $\M = \Mtaumaxstat(\D)$.
\item $\ldots$ \emph{time order and repeating ancestral relationships} is the background knowledge $\BRtora$ for which $\BRtora(\M) = 1$ if and only if $\M$ is time ordered and has repeating ancestral relationships.
\item $\ldots$ \emph{time order and repeating orientations} is the background knowledge $\BRtoro$ for which $\BRtoro(\M) = 1$ if and only if $\M$ is time ordered and has repeating orientations.
\end{itemize}
